window.__finlexDocLoaded(10180,{"id":10180,"articles":[{"id":1000751,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"Minimum tax targeting large multinational corporations ($500M+ 3-year average US gross receipts and >=3% base erosion percentage) that strip US taxable income via deductible payments (royalties, interest, services) to foreign related parties.","seq":0},{"id":1000752,"no":"IRC §59A","heading":"$500M Receipts Test, 3% Base Erosion Threshold & Modified Taxable Income","text":"• Applicable Taxpayer Test: (1) C corporation (not RIC/REIT/S corp); (2) 3-year average US effectively connected gross receipts >= $500M; (3) Base Erosion Percentage >= 3% (2% for banks/securities dealers).\n• Base Erosion Payments: Deductible payments to foreign related parties (interest, royalties, management/R&D fees) — generally EXCLUDING Cost of Goods Sold (COGS) and Services Cost Method (SCM) at-cost charges.\n• Computation: Excess of BEAT rate (10%, rising under scheduled statutory step-up) × Modified Taxable Income over regular tax liability reduced by certain credits.","seq":1},{"id":1000753,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• Operates alongside OECD Pillar Two UTPR as a defensive US inbound base-erosion backstop; accounted for as a period cost under ASC 740 (no deferred tax remeasurement).","seq":2},{"id":1000754,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (Office of the Law Revision Counsel (U.S. Code)): https://uscode.house.gov/\nStatus: in_force.","seq":3}]});
